    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xB415171CB23902CFULL + 0xD73C12E96086B1D3ULL);
