        //      aEarthLaneA (-->), aEarthLaneB (-->), aHeartLaneA (-->), aShadowLaneD (<-?->)
        //
        // Cross:
        //      aEarthLaneC (<--), aEarthLaneD (<--), aCrystalLaneA (<--), pSnowLaneD (<-?->)
        //
