            //
            aOrbiterF = ((aOrbiterF + aOrbiterJ) + 0xE575903892CD17E8ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0x38630B88CF6E85F5ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
