            aOrbiterG = ((aWandererD + RotL64(aScatter, 13U)) + 0x15B8FA7272F707C8ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterE = (((aWandererK + RotL64(aPrevious, 36U)) + RotL64(aCarry, 51U)) + 0xDE3F268E8FE23CA7ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterK = ((aWandererF + RotL64(aIngress, 5U)) + RotL64(aCarry, 19U)) + 0x912414E1946F63F3ULL;
            aOrbiterB = ((aWandererB + RotL64(aScatter, 51U)) + RotL64(aCarry, 5U)) + 0xEFB17B7579B256B5ULL;
            aOrbiterA = (aWandererI + RotL64(aCross, 23U)) + 0xA7CB672490C1E990ULL;
            //
