            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x12DD49B37AD34DABULL) + aTwistOrbiterUpdateSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x2768D0FAADCFE02BULL;
            aOrbiterK = RotL64((aOrbiterK * 0x70C84D73340551C5ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xF035A54764088550ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x878A13542709924BULL;
            aOrbiterB = RotL64((aOrbiterB * 0x640B704564B31913ULL), 35U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xCAF63CF9486EE6FEULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x7B2C2B2F60AE0A4BULL;
