            aWandererB = aWandererB ^ (((RotL64(aPrevious, 23U) + aOrbiterG) + RotL64(aOrbiterH, 43U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aCross, 19U) + RotL64(aOrbiterI, 35U)) + aOrbiterE) + RotL64(aCarry, 19U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 43U) + RotL64(aOrbiterB, 18U)) + aOrbiterC);
