            aCross ^= (RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 11965U)) & S_BLOCK1], 35U) ^ RotL64(aHeartLaneA[((aIndex + 11477U)) & S_BLOCK1], 46U));
