            aWandererF = aWandererF ^ ((RotL64(aCross, 37U) + aOrbiterB) + RotL64(aOrbiterA, 35U));
            aWandererK = aWandererK + ((RotL64(aPrevious, 51U) + RotL64(aOrbiterE, 60U)) + aOrbiterG);
