            aOrbiterG = (((aWandererK + RotL64(aScatter, 23U)) + RotL64(aCarry, 57U)) + 0x6F3E7712337BC27DULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 22U)) & S_SALT1];
