            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x6AA6925E39775E95ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xC11AA855436981FAULL;
            aOrbiterH = RotL64((aOrbiterH * 0x9F59FD8A716FAA63ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x509C6BE59305AD3EULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xCFC709FD3227B098ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x138D74945D6FA53FULL), 35U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0x3F72E8EB5E9D128CULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x36950235D2A6192FULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 18U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x951E135B644C3E93ULL), 47U);
