            aOrbiterD = RotL64((aOrbiterD * 0x22F3431B24128635ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xB29A6ADC8DD0BBFBULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xE0D3AAB22E9BD9EBULL;
            aOrbiterB = RotL64((aOrbiterB * 0xB3263660526B3615ULL), 5U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0x6EC977C6D8B8DC6AULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x8AC9071CBEEF7563ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x39CCFE91B2A0ACC5ULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x7355ED1F358C14ACULL;
