            aWandererG = aWandererG + (((RotL64(aScatter, 5U) + aOrbiterJ) + RotL64(aOrbiterG, 11U)) + RotL64(aCarry, 5U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 51U) + RotL64(aOrbiterB, 43U)) + aOrbiterH);
