            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x8691DA184CE9326CULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xD5C3C108792EF57CULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB1B951EB9056DAE9ULL), 21U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterB, 5U);
