            //
            aWandererE = aWandererE + ((((RotL64(aCross, 60U) + aOrbiterB) + RotL64(aOrbiterJ, 4U)) + RotL64(aCarry, 35U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 24U)) & S_SALT1]);
