            //
            aScatter = (RotL64(aCross, 4U) + RotL64(aPrevious, 47U)) + (RotL64(aIngress, 21U) ^ RotL64(aCarry, 35U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererD + RotL64(aIngress, 47U)) + RotL64(aCarry, 13U)) + 0xB9CAE4A664E09241ULL;
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 29U)) + 0x66FDBF0AD3582C9BULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aScatter, 58U)) + RotL64(aCarry, 29U)) + 0xCDFCFB394FCCCEA3ULL;
            aOrbiterG = ((aWandererF + RotL64(aCross, 41U)) + RotL64(aCarry, 53U)) + 0x87726AE72BC38963ULL;
            aOrbiterC = ((aWandererK + RotL64(aScatter, 5U)) + 0x43CCDB07C2F47D8EULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = (aWandererJ + RotL64(aIngress, 13U)) + 0x1D5EA4A9E1D105EFULL;
            aOrbiterE = (aWandererG + RotL64(aCross, 21U)) + 0x7B219EB291D9646EULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0x7506A1B215445892ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x2A1FC5AF3D0BFB85ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x70B69258870F0963ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x4C8A79F2587B0B7CULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x49ACAE89C526E2D0ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7A38CB36245F3721ULL), 57U);
