            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0xD369C10BE0FE3441ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0xDF0B087D1171AA91ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xF2DE8691A46130ABULL), 35U);
