            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x7E1C961BEA5972A7ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x28C5788A299BADEDULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x07D070BBCF4B07BDULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xA0C9D7599BAB904CULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x70B2E4D6EED2DC5FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA766077A8FBD3C45ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x0DBBA09D3EBDA03DULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0x15A6172425DA844FULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 9U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xC7B712DF8DAF13A7ULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xEF07B30D05A3F059ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xE15E2F829A709307ULL;
