            //
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 23U) + RotL64(aOrbiterH, 60U)) + aOrbiterG);
            aWandererA = aWandererA + (((RotL64(aScatter, 40U) + aOrbiterH) + RotL64(aOrbiterA, 35U)) + RotL64(aCarry, 13U));
            aWandererD = aWandererD ^ (((RotL64(aCross, 47U) + aOrbiterC) + RotL64(aOrbiterK, 53U)) + aKeyRotateAWandererUpdateSaltF[((aIndex + 23U)) & S_SALT1]);
